{
  "avaliacoes": [
    {
      "id": "E04b30ec5ac482a89",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O tipo de amarração do FPSO influencia o planejamento de inspeção, e o plano deve ser apropriado à vida esperada do sistema de ancoragem.",
          "trechos": [
            "E04b30ec5ac482a89:0:700"
          ],
          "condicoes": [
            "aplica-se a sistemas de amarração de FPSO em posição fixa",
            "depende das características do tipo específico de amarração"
          ],
          "limites": [
            "o trecho não detalha métodos de inspeção aérea ou submarina",
            "o trecho remete a orientações externas sem reproduzi-las integralmente"
          ]
        },
        {
          "proposicao": "Em linhas de amarração formadas por corrente, cabo de aço, cabo de fibra ou combinações, as conexões entre tipos ou diâmetros distintos devem ser consideradas potenciais pontos de fraqueza; boias subsuperficiais também podem compor o sistema.",
          "trechos": [
            "E04b30ec5ac482a89:0:700",
            "E04b30ec5ac482a89:700:1399"
          ],
          "condicoes": [
            "aplica-se quando a linha usa materiais mistos ou variações de diâmetro",
            "pode incluir suporte por boias subsuperficiais"
          ],
          "limites": [
            "o trecho não quantifica o risco associado a cada conexão",
            "não diferencia mecanismos de falha por material"
          ]
        },
        {
          "proposicao": "Um sistema de gestão de integridade para amarração deve incluir avaliação de mecanismos de deterioração, escopo de inspeção e critérios sugeridos de descarte; o desempenho pode ser apoiado por monitoramento de tensão, detecção de ruptura de linha e programas para limitar desgaste em fairleads.",
          "trechos": [
            "E04b30ec5ac482a89:700:1399",
            "E04b30ec5ac482a89:1399:2095",
            "E04b30ec5ac482a89:2095:2300"
          ],
          "condicoes": [
            "aplica-se ao gerenciamento de integridade de sistemas de ancoragem",
            "os mecanismos citados como típicos são desgaste, corrosão e fadiga"
          ],
          "limites": [
            "os critérios de descarte não são completos no trecho",
            "o trecho exemplifica mecanismos típicos, sem afirmar exaustividade"
          ]
        }
      ]
    },
    {
      "id": "E7276e1bbb61a86d6",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Uma função geral da estrutura oceânica de produção é suportar planta de processo, equipamentos de perfuração ou produção, e condutores ou risers de produção e extração.",
          "trechos": [
            "E7276e1bbb61a86d6:692:1389",
            "E7276e1bbb61a86d6:1389:2087"
          ],
          "condicoes": [
            "aplica-se ao contexto de estruturas oceânicas de produção de petróleo no mar"
          ],
          "limites": [
            "o trecho é geral e não trata diretamente de inspeção, corrosão, desgaste ou fadiga"
          ]
        },
        {
          "proposicao": "Na pré-seleção de uma instalação tipo FPSO, o sistema de posicionamento distingue arranjos como spread mooring com várias linhas em catenária simples ou com flutuadores ou pesos intermediários, ancoradas ao fundo e conectadas ao perímetro do navio.",
          "trechos": [
            "E7276e1bbb61a86d6:1389:2087"
          ],
          "condicoes": [
            "aplica-se ao caso de pré-seleção de instalação tipo FPSO",
            "o spread mooring pode usar flutuadores in-line spring buoys ou pesos clamp weights intermediários"
          ],
          "limites": [
            "o trecho não apresenta critérios de inspeção ou contingência",
            "não há comparação completa com outros sistemas no trecho disponível"
          ]
        },
        {
          "proposicao": "No spread mooring, a conexão das linhas ao perímetro do navio tende a manter o aproamento praticamente fixo.",
          "trechos": [
            "E7276e1bbb61a86d6:1389:2087",
            "E7276e1bbb61a86d6:2087:2211"
          ],
          "condicoes": [
            "aplica-se ao arranjo SMS descrito no trecho"
          ],
          "limites": [
            "o advérbio 'praticamente' indica que o aproamento não é absolutamente fixo",
            "o trecho não informa consequências operacionais dessa restrição sob extremos ambientais"
          ]
        }
      ]
    },
    {
      "id": "E11483a0c65448a26",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Os principais sistemas permanentes de amarração citados são amarração em ponto único, ancoragem distribuída e posicionamento dinâmico, com finalidades e arranjos distintos.",
          "trechos": [
            "E11483a0c65448a26:0:695",
            "E11483a0c65448a26:695:1384"
          ],
          "condicoes": [
            "aplica-se a estruturas flutuantes offshore",
            "o DP pode atuar em conjunto com outros sistemas de ancoragem"
          ],
          "limites": [
            "o trecho não aborda diretamente inspeção, reparo ou falhas",
            "a referência a ambientes menos agressivos para spread mooring é descritiva no texto, sem critérios mensuráveis no trecho"
          ]
        },
        {
          "proposicao": "A seleção da configuração das linhas de ancoragem considera tipo de plataforma, lâmina d'água, número de risers, intensidade das cargas e custo dos materiais.",
          "trechos": [
            "E11483a0c65448a26:1384:2084"
          ],
          "condicoes": [
            "aplica-se às configurações catenária, taut leg e tendões verticais"
          ],
          "limites": [
            "o trecho não hierarquiza nem quantifica a influência de cada fator"
          ]
        },
        {
          "proposicao": "Na configuração convencional em catenária, parte da linha fica apoiada no leito marinho, transmitindo apenas esforços horizontais à fundação; isso amplia o raio de abrangência e permite o uso de âncoras que não resistem a componentes verticais.",
          "trechos": [
            "E11483a0c65448a26:1384:2084",
            "E11483a0c65448a26:2084:2396"
          ],
          "condicoes": [
            "aplica-se à configuração convencional descrita",
            "o comprimento é indicado como aproximadamente duas a três vezes a lâmina d'água"
          ],
          "limites": [
            "há marcadores numéricos apagados em parte do trecho, então ângulos específicos não podem ser reconstruídos",
            "o trecho trata do comportamento geométrico, não do desempenho em corrosão, desgaste ou fadiga"
          ]
        }
      ]
    },
    {
      "id": "E256ac88faae72067",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Os sistemas de ancoragem restringem deslocamentos causados por carregamento ambiental para manter a unidade dentro de uma região operacional segura, e sua eficiência pode ser expressa pelo passeio sob condição severa.",
          "trechos": [
            "E256ac88faae72067:0:698",
            "E256ac88faae72067:698:1398"
          ],
          "condicoes": [
            "aplica-se a unidades flutuantes offshore",
            "o passeio é medido a partir da posição de equilíbrio neutro até a posição sob carregamento ambiental"
          ],
          "limites": [
            "o trecho não define limites operacionais aceitáveis de passeio",
            "não explicita procedimentos de resposta quando a região segura é excedida"
          ]
        },
        {
          "proposicao": "Maior rigidez do sistema tende a reduzir o passeio, mas o material das linhas limita essa rigidez porque o aumento da rigidez eleva as trações e tensões internas nas linhas.",
          "trechos": [
            "E256ac88faae72067:698:1398"
          ],
          "condicoes": [
            "aplica-se ao dimensionamento e seleção de materiais das linhas de ancoragem"
          ],
          "limites": [
            "o trecho não compara materiais específicos",
            "não fornece valores de tração, tensão ou rigidez"
          ]
        },
        {
          "proposicao": "A composição do sistema deve garantir integridade durante a operação, incluindo evitar falha por fadiga; a escolha do tipo de ancoragem depende da geometria das linhas, tipo de embarcação e operação, quantidade de risers, custo e profundidade do mar.",
          "trechos": [
            "E256ac88faae72067:698:1398",
            "E256ac88faae72067:1398:2098",
            "E256ac88faae72067:2098:2167"
          ],
          "condicoes": [
            "aplica-se à seleção entre SPM, spread mooring e configurações geométricas como catenária, taut leg e tendões"
          ],
          "limites": [
            "o trecho afirma a necessidade de integridade e resistência à fadiga, mas não descreve métodos de inspeção ou substituição",
            "não trata explicitamente de ruptura de linha ou arraste de âncora"
          ]
        }
      ]
    },
    {
      "id": "E3132ede1edc4dcf7",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Os sistemas principais de amarração listados são ponto único, spread mooring e posicionamento dinâmico; o DP pode operar em conjunto com outros sistemas.",
          "trechos": [
            "E3132ede1edc4dcf7:0:699",
            "E3132ede1edc4dcf7:699:1398"
          ],
          "condicoes": [
            "aplica-se a estruturas flutuantes utilizadas em ambientes offshore"
          ],
          "limites": [
            "o trecho não aborda inspeção, reparo ou contingência diretamente"
          ]
        },
        {
          "proposicao": "As configurações de linhas de ancoragem mais usadas são catenária, taut leg e tendões verticais, escolhidas conforme tipo de plataforma, lâmina d'água, número de risers, intensidade das cargas e custo dos materiais.",
          "trechos": [
            "E3132ede1edc4dcf7:1398:2088"
          ],
          "condicoes": [
            "aplica-se à seleção de configuração das linhas"
          ],
          "limites": [
            "o trecho não fornece critérios quantitativos de seleção"
          ]
        },
        {
          "proposicao": "Na catenária convencional, a linha apoiada no leito marinho transmite esforços horizontais à fundação e exige maior raio de abrangência, da ordem de duas a três vezes a lâmina d'água.",
          "trechos": [
            "E3132ede1edc4dcf7:1398:2088",
            "E3132ede1edc4dcf7:2088:2382"
          ],
          "condicoes": [
            "aplica-se à configuração convencional descrita"
          ],
          "limites": [
            "o trecho exibido termina antes de completar a explicação sobre as âncoras associadas",
            "não há relação direta com corrosão, desgaste, fadiga ou inspeção submarina no excerto"
          ]
        }
      ]
    },
    {
      "id": "E154caa7b6599c343",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A escolha do tipo de ancoragem depende da geometria das linhas e, principalmente, do tipo de embarcação e operação, quantidade de risers, custo e profundidade do mar; para cada geometria há um tipo apropriado de fundação.",
          "trechos": [
            "E154caa7b6599c343:0:690"
          ],
          "condicoes": [
            "aplica-se à seleção entre catenária convencional, taut leg e tendões verticais"
          ],
          "limites": [
            "o trecho não detalha o mapeamento completo entre geometria e fundação",
            "não apresenta critérios de inspeção ou substituição"
          ]
        },
        {
          "proposicao": "Na ancoragem em catenária, maiores deslocamentos da plataforma são admitidos, e o atrito do trecho apoiado no leito marinho absorve parte das solicitações, reduzindo esforços na âncora.",
          "trechos": [
            "E154caa7b6599c343:690:1388"
          ],
          "condicoes": [
            "aplica-se à ancoragem em catenária livre ou convencional"
          ],
          "limites": [
            "o trecho não quantifica os deslocamentos admissíveis",
            "a redução de esforços é apresentada de forma descritiva, sem valores"
          ]
        },
        {
          "proposicao": "A catenária demanda raio de ancoragem elevado e pode gerar interferência com linhas de outras unidades ou equipamentos submarinos; já a taut leg usa linhas inclinadas e tracionadas, com menor comprimento, maior rigidez e menor passeio, exigindo âncoras com alta resistência a arrancamento axial.",
          "trechos": [
            "E154caa7b6599c343:1388:2088",
            "E154caa7b6599c343:2088:2259"
          ],
          "condicoes": [
            "aplica-se à comparação entre catenária e taut leg",
            "a catenária pode ser usada em semi-submersíveis e FPSOs"
          ],
          "limites": [
            "há marcador numérico apagado no ângulo de topo da taut leg, que não pode ser reconstruído",
            "o trecho não discute inspeção por ROV, corrosão ou fadiga dessas configurações"
          ]
        }
      ]
    }
  ],
  "concluir": false,
